import { PlusIcon } from '@phosphor-icons/react';
import { Button, Group, Input, Stack, Text, TextInput } from '@mantine/core';
import { formRootRule, isNotEmpty, useForm } from '@mantine/form';
import { randomId } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';
import { Address, AddressCard } from './AddressCard';

interface ContactValues {
  name: string;
  addresses: Address[];
}

export function NestedAddresses() {
  const form = useForm<ContactValues>({
    initialValues: {
      name: '',
      addresses: [
        {
          key: randomId(),
          label: 'Home',
          street: '12 Baker St',
          city: 'London',
          isPrimary: true,
        },
        {
          key: randomId(),
          label: 'Office',
          street: '',
          city: '',
          isPrimary: false,
        },
      ],
    },
    validate: {
      name: isNotEmpty('Name is required'),
      addresses: {
        [formRootRule]: (value) =>
          value.filter((address) => address.isPrimary).length === 1
            ? null
            : 'Exactly one address must be primary',
        label: isNotEmpty('Label is required'),
        street: isNotEmpty('Street is required'),
      },
    },
  });

  const addresses = form.useWatchValue('addresses');

  const handleSubmit = (values: ContactValues) => {
    const primary = values.addresses.find((address) => address.isPrimary);
    notifications.show({
      title: 'Contact saved',
      message: `${values.name}: ${values.addresses.length} addresses, primary is ${primary?.label}`,
    });
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit)}>
      <Stack>
        <TextInput
          size="md"
          label="Name"
          placeholder="Jane Doe"
          withAsterisk
          {...form.getInputProps('name')}
        />

        {addresses.map((address, index) => (
          <AddressCard key={address.key} form={form} index={index} />
        ))}

        {addresses.length === 0 && (
          <Text size="sm" ta="center">
            No addresses yet
          </Text>
        )}

        {form.errors.addresses && <Input.Error size="md">{form.errors.addresses}</Input.Error>}

        <Group>
          <Button
            variant="default"
            leftSection={<PlusIcon size={16} />}
            onClick={() =>
              form.insertListItem('addresses', {
                key: randomId(),
                label: '',
                street: '',
                city: '',
                isPrimary: addresses.length === 0,
              })
            }
          >
            Add address
          </Button>
        </Group>

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Save contact
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { TrashIcon } from '@phosphor-icons/react';
import {
  ActionIcon,
  Badge,
  Button,
  Group,
  Paper,
  SimpleGrid,
  Stack,
  Text,
  TextInput,
} from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';

export interface Address {
  key: string;
  label: string;
  street: string;
  city: string;
  isPrimary: boolean;
}

interface AddressCardProps {
  form: UseFormReturnType<{ addresses: Address[] }>;
  index: number;
}

export function AddressCard({ form, index }: AddressCardProps) {
  const isPrimary = form.useWatchValue(`addresses.${index}.isPrimary`);

  const setPrimary = () => {
    const current = form.getValues().addresses;
    const primaryIndex = current.findIndex((address) => address.isPrimary);

    if (primaryIndex !== -1 && primaryIndex !== index) {
      form.replaceListItem('addresses', primaryIndex, {
        ...current[primaryIndex],
        isPrimary: false,
      });
    }

    form.replaceListItem('addresses', index, { ...current[index], isPrimary: true });
  };

  return (
    <Paper withBorder p="md">
      <Stack gap="sm">
        <Group justify="space-between" wrap="nowrap">
          <Group gap="xs">
            <Text fw={500} size="sm">
              Address {index + 1}
            </Text>
            {isPrimary && <Badge size="sm">Primary</Badge>}
          </Group>

          <Group gap="xs" wrap="nowrap">
            <Button size="compact-xs" variant="default" disabled={isPrimary} onClick={setPrimary}>
              Set as primary
            </Button>

            <ActionIcon
              variant="default"
              aria-label="Remove address"
              onClick={() => form.removeListItem('addresses', index)}
            >
              <TrashIcon size={18} color="var(--mantine-color-red-6)" />
            </ActionIcon>
          </Group>
        </Group>

        <TextInput
          size="md"
          label="Label"
          placeholder="Home"
          withAsterisk
          {...form.getInputProps(`addresses.${index}.label`)}
        />

        <SimpleGrid cols={{ base: 1, sm: 2 }}>
          <TextInput
            size="md"
            label="Street"
            placeholder="12 Baker St"
            withAsterisk
            {...form.getInputProps(`addresses.${index}.street`)}
          />

          <TextInput
            size="md"
            label="City"
            placeholder="London"
            {...form.getInputProps(`addresses.${index}.city`)}
          />
        </SimpleGrid>
      </Stack>
    </Paper>
  );
}
